insert into ai_knowledge (title, content, embedding, language) values ('booking-help', 'Pour réserver une course :

1. Sur l''accueil, touchez « Où allez-vous ? » et choisissez une destination.
2. Sélectionnez le type de véhicule (moto, taxi, tricycle, camion).
3. Consultez l''estimation du tarif, de la distance et du temps d''arrivée.
4. Confirmez. L''écran « Recherche d''un prestataire… » s''affiche.
5. Un prestataire accepte : vous voyez sa carte (nom, véhicule, plaque, note) et son suivi en direct.
6. À l''arrivée, le tarif est confirmé et vous pouvez noter la course (1 à 5 étoiles).

Le paiement se fait en espèces. Vous pouvez annuler à tout moment avant la prise en charge.', '[0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.213201,0.000000,0.000000,0.071067,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.071067,0.071067,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.142134,0.071067,0.071067,0.071067,0.142134,0.071067,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.071067,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.142134,0.000000,0.000000,0.000000,0.000000,0.000000,0.142134,0.000000,0.284268,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.071067,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.142134,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.142134,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.213201,0.000000,0.000000,0.000000,0.000000,0.000000,0.284268,0.000000,0.000000,0.000000,0.000000,0.071067,0.000000,0.000000,0.000000,0.000000,0.000000,0.071067,0.000000,0.000000,0.000000,0.000000,0.000000,0.071067,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.071067,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000