insert into ai_knowledge (title, content, embedding, language) values ('provider-requirements', 'Pour devenir prestataire GoBert, suivez ces étapes :

1. **Identité** : renseignez votre nom complet et votre numéro de téléphone (+237).
2. **Véhicule** : indiquez le type (moto, taxi, tricycle, camion), la marque, le modèle, l''immatriculation (ex. EST 123 AB) et l''année.
3. **Documents** : importez une photo de votre pièce d''identité (CNI), de votre permis de conduire et de la carte grise du véhicule. Les images sont compressées à moins de 200 Ko.
4. **Services** : décrivez vos services (FR/EN), les prix et les zones couvertes.
5. **Horaires** : définissez vos jours et heures de disponibilité, ou activez le 24h/24.
6. **Vérification** : relisez et soumettez. Votre dossier passe en **en attente** de validation par un administrateur.

Une fois approuvé, votre profil apparaît sur la carte des passagers et vous pouvez recevoir des courses.', '[0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.057073,0.000000,0.000000,0.000000,0.057073,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.057073,0.057073,0.000000,0.000000,0.057073,0.000000,0.000000,0.057073,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.057073,0.114146,0.057073,0.057073,0.057073,0.057073,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.057073,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.057073,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.057073,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.114146,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.057073,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.456584,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.057073,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.057073,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.057073,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.171219,0.000000,0.000000,0.000000,0.000000,0.000000,0.399511,0.000000,0.000000,0.000000,0.057073,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.057073,0.114146,0.000000,0.000000,0.000000,0.000000,0.000000,0