insert into ai_knowledge (title, content, embedding, language) values ('services', 'GoBert propose 5 services à Bertoua et dans les régions de l''Est, de l''Adamaoua, du Nord et de l''Extrême-Nord :

- **Moto** : trajets rapides en ville, dès 300 XAF.
- **Course (Taxi)** : trajets confortables, dès 500 XAF.
- **Express** : livraison de colis, dès 500 XAF.
- **Cargo** : transport de marchandises, dès 1000 XAF.
